// Color configuration for the Tesoro Boricua application
// Update colors here to change them across the entire app

export const colors = {
  // Sidebar colors
  translateSidebarBg: '#ff0000ff',
  boribotSidebarBg: '#22c55e', // Green
  boribotSendBtn: '#22c55e', // Green send button
  boribotMessageBorder: '#22c55e', // Green message border
  boribotTextColor: '#16a34a', // Darker green for text

  // Header colors
  headerBg: 'linear-gradient(135deg, #007bff 0%, #0056b3 100%)',
  headerText: '#fff',

  // Button colors
  buttonPrimary: '#007bff',
  buttonSuccess: '#27ae60',
  buttonDanger: '#dc3545',
  buttonSecondary: '#6c757d',

  // Tile colors
  tileLanguage: '#27ae60',
  tileDiscover: '#3498db',
  tileRecipes: '#fd7e14',
  tileMusic: '#e74c3c',
  tileHistory: '#0006b1ff',
  tileCommunity: '#1abc9c',

  // Text colors
  textPrimary: '#333',
  textSecondary: '#6c757d',
  textLight: '#fff',
};
